<?php
/**
 * Contact-data normalisation shared by the public forms, the admin CRUD engine and validate():
 *
 *   Phone   phone_parse() / phone_normalize() / phone_error() — international numbers validated per country with the
 *           libphonenumber metadata in app/data/phone_meta.json (generated by tools/gen-phone-meta.cjs from the same
 *           libphonenumber-js version the browser uses, so client and server agree) and normalised to E.164
 *           (+919876543210). Numbers without a country code use the form's country, else setting
 *           phone_default_country (IN): existing 10-digit Indian numbers stay valid (+91 assumed).
 *   Email   email_normalize() (trim, strip "mailto:", lowercase, IDN domain -> ASCII/punycode) + email_is_valid()
 *           (strict dot-atom local part, real hostname labels, alphabetic or IDN TLD).
 *   Address address_country() (ISO2 / name / alias -> canonical), address_india_states(), address_state_normalize(),
 *           address_postal_error() (India 6-digit PIN, ZIP, postcodes … per country), address_postal_label().
 *
 * Keep the client copies in sync: frontend/site/forms/{phone,email,address}.ts and
 * frontend/src/components/ui/PhoneInput.tsx use the same messages.
 */

/* ============================================================================ Phone */

/**
 * Decoded app/data/phone_meta.json (cached for the request). When OPcache is enabled (production), the 117 KB JSON is
 * compiled once into a PHP array file (storage/cache/phone_meta.php) that OPcache keeps in shared memory, so pages with
 * phone fields no longer decode the JSON on every request; the file is rebuilt whenever the JSON is newer. Without
 * OPcache (e.g. a default XAMPP) the JSON is decoded as before.
 */
function phone_meta(): array
{
    static $meta = null;
    if ($meta === null) {
        $file = APP_ROOT . '/app/data/phone_meta.json';
        // only worth it with OPcache (production): without it, parsing the PHP file is slower than json_decode
        $useCache = extension_loaded('Zend OPcache') && filter_var(ini_get('opcache.enable'), FILTER_VALIDATE_BOOLEAN) && PHP_SAPI !== 'cli';
        $cache = (defined('STORAGE_PATH') ? STORAGE_PATH : APP_ROOT . '/storage') . '/cache/phone_meta.php';
        $meta = [];
        if ($useCache && is_file($cache) && is_file($file) && filemtime($cache) >= filemtime($file)) {
            $meta = (static fn () => include $cache)();
            $meta = is_array($meta) ? $meta : [];
        }
        if (!$meta && is_file($file)) {
            $meta = json_decode((string) file_get_contents($file), true) ?: [];
            if ($useCache && $meta && is_dir(dirname($cache)) && is_writable(dirname($cache))) {
                $tmp = $cache . '.' . bin2hex(random_bytes(4)) . '.tmp';
                if (@file_put_contents($tmp, "<?php\n// generated from app/data/phone_meta.json by phone_meta() - do not edit\nreturn " . var_export($meta, true) . ";\n", LOCK_EX) !== false) {
                    @rename($tmp, $cache); // atomic swap: concurrent requests never include a half-written file
                } else {
                    @unlink($tmp);
                }
            }
        }
        $meta += ['codes' => [], 'regions' => [], 'nongeo' => []];
    }
    return $meta;
}

/** Default region for numbers typed without a country code (setting phone_default_country, else IN). */
function phone_default_country(): string
{
    static $c = null;
    if ($c === null) {
        $v = strtoupper(trim((string) (function_exists('setting') ? setting('phone_default_country', 'IN') : 'IN')));
        $c = isset(phone_meta()['regions'][$v]) ? $v : 'IN';
    }
    return $c;
}

/** Full match of a libphonenumber pattern. */
function phone_match(string $digits, ?string $pattern): bool
{
    if ($pattern === null || $pattern === '') {
        return false;
    }
    return (bool) @preg_match('/^(?:' . $pattern . ')$/', $digits);
}

/**
 * Number type of a national number for a region (libphonenumber getNumberType()):
 * fixed_line | mobile | fixed_line_or_mobile | toll_free | premium_rate | personal_number | voicemail | uan | pager | voip |
 * shared_cost, or null when the number is not valid for the region.
 */
function phone_number_type(string $nn, array $r): ?string
{
    if (!phone_match($nn, $r['p'] ?? null)) {
        return null;
    }
    $t = $r['t'] ?? [];
    $is = function (string $k) use ($t, $nn): bool {
        if (!isset($t[$k]) || ($t[$k][0] ?? '') === '') {
            return false;
        }
        if (!empty($t[$k][1]) && !in_array(strlen($nn), $t[$k][1], true)) {
            return false;
        }
        return phone_match($nn, $t[$k][0]);
    };
    if ($is('f')) {
        if (!isset($t['m']) || ($t['m'][0] ?? '') === '' || $is('m')) {
            return 'fixed_line_or_mobile';
        }
        return 'fixed_line';
    }
    foreach (['m' => 'mobile', 'pr' => 'premium_rate', 'tf' => 'toll_free', 'sc' => 'shared_cost', 'v' => 'voip', 'pn' => 'personal_number', 'pg' => 'pager', 'u' => 'uan', 'vm' => 'voicemail'] as $k => $name) {
        if ($is($k)) {
            return $name;
        }
    }
    return null;
}

/** Strip a national (trunk) prefix such as the leading 0 of "09876543210" (libphonenumber extractNationalNumber()). */
function phone_strip_national_prefix(string $digits, array $r): string
{
    $npp = $r['npp'] ?? ($r['np'] ?? null);
    if ($npp === null || $npp === '' || !@preg_match('/^(?:' . $npp . ')/', $digits, $m) || $m[0] === '') {
        return $digits;
    }
    $groups = count($m) - 1;
    $stripped = !empty($r['npt']) && $groups > 0 && ($m[$groups] ?? '') !== ''
        ? (string) preg_replace('/^(?:' . $npp . ')/', $r['npt'], $digits, 1)
        : substr($digits, strlen($m[0]));
    // keep the original when stripping would turn a valid number into an invalid one
    if ($stripped === '' || (!phone_match($stripped, $r['p'] ?? null) && phone_match($digits, $r['p'] ?? null))) {
        return $digits;
    }
    return $stripped;
}

/**
 * Region (ISO2, or "001" for non-geographic numbers) + validity of a national number under a calling code.
 * Like libphonenumber, the national (trunk) prefix is stripped with the numbering plan of $planRegion (the default
 * region for nationally typed numbers) or of the calling code's main region, then the region is chosen by leading
 * digits / number type among the regions sharing the calling code (+1: US, CA, JM …; +44: GB, GG, JE, IM; +7: RU, KZ).
 */
function phone_resolve(string $cc, string $nn, ?string $planRegion = null): array
{
    $meta = phone_meta();
    if (isset($meta['nongeo'][$cc])) {
        $r = $meta['nongeo'][$cc];
        $nn = phone_strip_national_prefix($nn, $r);
        $type = phone_number_type($nn, $r);
        return ['country' => '001', 'national' => $nn, 'type' => $type, 'valid' => $type !== null, 'possible' => in_array(strlen($nn), $r['l'] ?? [], true)];
    }
    $regions = $meta['codes'][$cc] ?? [];
    $plan = $planRegion && in_array($planRegion, $regions, true) ? $planRegion : ($regions[0] ?? null);
    if ($plan && isset($meta['regions'][$plan])) {
        $nn = phone_strip_national_prefix($nn, $meta['regions'][$plan]);
    }
    foreach ($regions as $iso) {
        $r = $meta['regions'][$iso] ?? null;
        if (!$r || (!empty($r['ld']) && !@preg_match('/^(?:' . $r['ld'] . ')/', $nn))) {
            continue;
        }
        $type = phone_number_type($nn, $r);
        if ($type !== null) {
            return ['country' => $iso, 'national' => $nn, 'type' => $type, 'valid' => true, 'possible' => true];
        }
    }
    $main = $plan ?? ($regions[0] ?? null);
    $possible = $main && in_array(strlen($nn), $meta['regions'][$main]['l'] ?? [], true);
    return ['country' => $main, 'national' => $nn, 'type' => null, 'valid' => false, 'possible' => $possible];
}

/**
 * Analyse a phone number typed in any common format ("+91 98765 43210", "098765 43210", "0091-9876543210",
 * "919876543210", "(020) 7946 0018" with country GB …).
 * @return array{input:string, e164:?string, country:?string, calling_code:?string, national:?string, valid:bool, possible:bool, type:?string}
 */
function phone_parse(?string $raw, ?string $defaultCountry = null): array
{
    $input = trim((string) $raw);
    $out = ['input' => $input, 'e164' => null, 'country' => null, 'calling_code' => null, 'national' => null, 'valid' => false, 'possible' => false, 'type' => null];
    if ($input === '') {
        return $out;
    }
    $meta = phone_meta();
    // drop an extension ("ext. 21", "x21", "#21") — E.164 has no place for it
    $main = (string) preg_replace('/\s*(?:ext\.?|extension|x|#)\s*\d{1,6}\s*$/i', '', $input);
    // full-width / Arabic-Indic digits -> ASCII
    $main = strtr($main, ['０' => '0', '１' => '1', '２' => '2', '３' => '3', '４' => '4', '５' => '5', '６' => '6', '７' => '7', '８' => '8', '９' => '9', '＋' => '+',
        '٠' => '0', '١' => '1', '٢' => '2', '٣' => '3', '٤' => '4', '٥' => '5', '٦' => '6', '٧' => '7', '٨' => '8', '٩' => '9']);
    if (preg_match('/[A-Za-z]/', $main)) {
        return $out; // letters (vanity numbers, typos) are never accepted
    }
    $plus = (bool) preg_match('/^[\s(\[]*\+/', $main);
    $digits = (string) preg_replace('/\D+/', '', $main);
    if ($digits === '' || strlen($digits) > 17) {
        return $out;
    }
    $intl = function (string $d) use ($meta): ?array {
        for ($n = 1; $n <= 3 && $n < strlen($d); $n++) {
            $cc = substr($d, 0, $n);
            if (isset($meta['codes'][$cc]) || isset($meta['nongeo'][$cc])) {
                return ['cc' => $cc] + phone_resolve($cc, substr($d, $n));
            }
        }
        return null;
    };
    $finish = function (?array $res) use ($out): array {
        if (!$res || empty($res['cc'])) {
            return $out;
        }
        $out['calling_code'] = $res['cc'];
        $out['country'] = $res['country'];
        $out['national'] = $res['national'];
        $out['valid'] = (bool) $res['valid'];
        $out['possible'] = (bool) ($res['possible'] || $res['valid']);
        $out['type'] = $res['type'];
        $out['e164'] = '+' . $res['cc'] . (string) $res['national'];
        return $out;
    };

    if ($plus) {
        return $finish($intl($digits));
    }
    $region = strtoupper(trim((string) $defaultCountry)) ?: phone_default_country();
    $r = $meta['regions'][$region] ?? ($meta['regions'][$region = phone_default_country()] ?? null);
    if (!$r) {
        return $finish($intl($digits));
    }
    $cc = (string) $r['c'];
    // "0091 98765 43210" / "011 44 …": international (IDD) prefix of the default region
    if (!empty($r['i']) && @preg_match('/^(?:' . $r['i'] . ')/', $digits, $m) && $m[0] !== '') {
        $res = $intl(substr($digits, strlen($m[0])));
        if ($res && $res['valid']) {
            return $finish($res);
        }
    }
    $res = ['cc' => $cc] + phone_resolve($cc, $digits, $region);
    if ($res['valid']) {
        return $finish($res);
    }
    // "919876543210": country code typed without the plus sign
    if (str_starts_with($digits, $cc) && strlen($digits) > strlen($cc) + 3) {
        $alt = ['cc' => $cc] + phone_resolve($cc, substr($digits, strlen($cc)), $region);
        if ($alt['valid']) {
            return $finish($alt);
        }
    }
    return $finish($res);
}

/** E.164 form of a valid number ("+919876543210"), null when empty or invalid. */
function phone_normalize(?string $raw, ?string $defaultCountry = null): ?string
{
    $p = phone_parse($raw, $defaultCountry);
    return $p['valid'] ? $p['e164'] : null;
}

function phone_is_valid(?string $raw, ?string $defaultCountry = null): bool
{
    return phone_parse($raw, $defaultCountry)['valid'];
}

/**
 * Validation message for a phone number (null when empty or valid) — identical to the browser messages
 * (frontend/site/forms/phone.ts phoneError()).
 */
function phone_error(?string $raw, ?string $defaultCountry = null): ?string
{
    if (trim((string) $raw) === '') {
        return null;
    }
    $p = phone_parse($raw, $defaultCountry);
    if ($p['valid']) {
        return null;
    }
    return phone_invalid_message($p['country'] && $p['country'] !== '001' ? $p['country'] : null);
}

/** "Enter a valid phone number for India (+91)." */
function phone_invalid_message(?string $country): string
{
    $r = $country ? (phone_meta()['regions'][$country] ?? null) : null;
    return $r ? 'Enter a valid phone number for ' . phone_country_name($country) . ' (+' . $r['c'] . ').' : 'Enter a valid phone number, including the country code.';
}

/** English country name for an ISO2 code, in plain letters (" & " -> " and ", no brackets) — "India", "St. Kitts and Nevis". */
function phone_country_name(string $iso): string
{
    $name = (string) (phone_meta()['regions'][strtoupper($iso)]['n'] ?? strtoupper($iso));
    return address_plain_name($name);
}

/** Calling code ("91") of a region, '' when unknown. */
function phone_calling_code(string $iso): string
{
    return (string) (phone_meta()['regions'][strtoupper($iso)]['c'] ?? '');
}

/** All regions: [['iso' => 'IN', 'name' => 'India', 'dial' => '91'], …] sorted by name. */
function phone_countries(): array
{
    static $list = null;
    if ($list === null) {
        $list = [];
        foreach (phone_meta()['regions'] as $iso => $r) {
            $list[] = ['iso' => $iso, 'name' => address_plain_name((string) $r['n']), 'dial' => (string) $r['c']];
        }
        usort($list, fn ($a, $b) => strcmp(address_sort_key($a['name']), address_sort_key($b['name'])));
    }
    return $list;
}

/** Countries listed first in phone / country selectors (India, then the most common origins of GIMT applicants). */
function phone_preferred_countries(): array
{
    return ['IN', 'NP', 'BD', 'BT', 'LK', 'AE', 'SA', 'QA', 'KW', 'OM', 'BH', 'US', 'GB', 'CA', 'AU', 'SG'];
}

/** Readable international form for display, e.g. "+91 98765 43210" (simple grouping; E.164 stays the stored value). */
function phone_display(?string $value): string
{
    $p = phone_parse($value);
    if (!$p['valid']) {
        return (string) $value;
    }
    $nn = (string) $p['national'];
    if ($p['calling_code'] === '91' && strlen($nn) === 10) {
        return '+91 ' . substr($nn, 0, 5) . ' ' . substr($nn, 5);
    }
    return '+' . $p['calling_code'] . ' ' . trim(chunk_split($nn, strlen($nn) > 8 ? 4 : 3, ' '));
}

/* ============================================================================ Email */

/**
 * Normalised email address: trimmed, whitespace and "mailto:" removed, lowercased, internationalised domain converted
 * to ASCII (punycode). Returns null for empty input. Does not validate — see email_is_valid().
 */
function email_normalize(?string $email): ?string
{
    $e = (string) preg_replace('/\s+/u', '', (string) $email);
    $e = (string) preg_replace('/^mailto:/i', '', trim($e, "<>\"'"));
    if ($e === '') {
        return null;
    }
    $at = strrpos($e, '@');
    if ($at === false) {
        return mb_strtolower($e);
    }
    $local = mb_strtolower(substr($e, 0, $at));
    $domain = rtrim(str_replace(['。', '．', '｡'], '.', mb_strtolower(substr($e, $at + 1))), '.');
    $ascii = email_idn_to_ascii($domain);
    return $local . '@' . ($ascii ?? $domain);
}

/** Strict format check of a (normalised) email address. */
function email_is_valid(?string $email): bool
{
    $e = email_normalize($email);
    if ($e === null || strlen($e) > 254 || substr_count($e, '@') !== 1) {
        return false;
    }
    [$local, $domain] = explode('@', $e);
    if ($local === '' || strlen($local) > 64 || !preg_match("/^[a-z0-9!#$%&'*+\\/=?^_`{|}~-]+(?:\\.[a-z0-9!#$%&'*+\\/=?^_`{|}~-]+)*$/", $local)) {
        return false;
    }
    if (strlen($domain) > 253) {
        return false;
    }
    $labels = explode('.', $domain);
    if (count($labels) < 2) {
        return false;
    }
    foreach ($labels as $label) {
        if ($label === '' || strlen($label) > 63 || !preg_match('/^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/', $label)) {
            return false;
        }
    }
    $tld = end($labels);
    if (!preg_match('/^(?:[a-z]{2,63}|xn--[a-z0-9-]{1,59})$/', $tld)) {
        return false;
    }
    return filter_var($e, FILTER_VALIDATE_EMAIL) !== false;
}

/** Validation message for an email address (null when empty or valid) — same text as the browser. */
function email_error(?string $email): ?string
{
    if (email_normalize($email) === null) {
        return null;
    }
    return email_is_valid($email) ? null : 'Enter a valid email address.';
}

/** IDN domain -> ASCII ("bücher.de" -> "xn--bcher-kva.de"); null when it cannot be converted. */
function email_idn_to_ascii(string $domain): ?string
{
    if ($domain === '' || !preg_match('/[^\x20-\x7e]/', $domain)) {
        return $domain;
    }
    if (function_exists('idn_to_ascii')) {
        $r = @idn_to_ascii($domain, defined('IDNA_NONTRANSITIONAL_TO_ASCII') ? IDNA_NONTRANSITIONAL_TO_ASCII : 0, defined('INTL_IDNA_VARIANT_UTS46') ? INTL_IDNA_VARIANT_UTS46 : 1);
        if (is_string($r) && $r !== '') {
            return strtolower($r);
        }
    }
    $out = [];
    foreach (explode('.', $domain) as $label) {
        if (!preg_match('/[^\x20-\x7e]/', $label)) {
            $out[] = $label;
            continue;
        }
        $enc = punycode_encode($label);
        if ($enc === null) {
            return null;
        }
        $out[] = 'xn--' . $enc;
    }
    return implode('.', $out);
}

/** RFC 3492 punycode encoding of one label (without the "xn--" prefix); null on overflow. */
function punycode_encode(string $input): ?string
{
    $cps = [];
    foreach (preg_split('//u', $input, -1, PREG_SPLIT_NO_EMPTY) ?: [] as $ch) {
        $cps[] = mb_ord($ch, 'UTF-8');
    }
    $base = 36;
    $tmin = 1;
    $tmax = 26;
    $skew = 38;
    $damp = 700;
    $n = 128;
    $delta = 0;
    $bias = 72;
    $output = '';
    foreach ($cps as $c) {
        if ($c < 0x80) {
            $output .= chr($c);
        }
    }
    $b = $h = strlen($output);
    if ($b > 0) {
        $output .= '-';
    }
    $digit = fn (int $d): string => chr($d + 22 + 75 * ($d < 26 ? 1 : 0));
    $adapt = function (int $delta, int $numPoints, bool $first) use ($base, $tmin, $tmax, $skew, $damp): int {
        $delta = $first ? intdiv($delta, $damp) : intdiv($delta, 2);
        $delta += intdiv($delta, $numPoints);
        $k = 0;
        while ($delta > intdiv(($base - $tmin) * $tmax, 2)) {
            $delta = intdiv($delta, $base - $tmin);
            $k += $base;
        }
        return $k + intdiv(($base - $tmin + 1) * $delta, $delta + $skew);
    };
    $total = count($cps);
    while ($h < $total) {
        $m = PHP_INT_MAX;
        foreach ($cps as $c) {
            if ($c >= $n && $c < $m) {
                $m = $c;
            }
        }
        if (($m - $n) > intdiv(PHP_INT_MAX - $delta, $h + 1)) {
            return null;
        }
        $delta += ($m - $n) * ($h + 1);
        $n = $m;
        foreach ($cps as $c) {
            if ($c < $n) {
                $delta++;
            }
            if ($c === $n) {
                $q = $delta;
                for ($k = $base; ; $k += $base) {
                    $t = $k <= $bias ? $tmin : ($k >= $bias + $tmax ? $tmax : $k - $bias);
                    if ($q < $t) {
                        break;
                    }
                    $output .= $digit($t + ($q - $t) % ($base - $t));
                    $q = intdiv($q - $t, $base - $t);
                }
                $output .= $digit($q);
                $bias = $adapt($delta, $h + 1, $h === $b);
                $delta = 0;
                $h++;
            }
        }
        $delta++;
        $n++;
    }
    return $output;
}

/* ============================================================================ Address */

/** States and union territories of India (official names). */
function address_india_states(): array
{
    return [
        'Andhra Pradesh', 'Arunachal Pradesh', 'Assam', 'Bihar', 'Chhattisgarh', 'Goa', 'Gujarat', 'Haryana', 'Himachal Pradesh', 'Jharkhand',
        'Karnataka', 'Kerala', 'Madhya Pradesh', 'Maharashtra', 'Manipur', 'Meghalaya', 'Mizoram', 'Nagaland', 'Odisha', 'Punjab', 'Rajasthan',
        'Sikkim', 'Tamil Nadu', 'Telangana', 'Tripura', 'Uttar Pradesh', 'Uttarakhand', 'West Bengal',
        // union territories
        'Andaman and Nicobar Islands', 'Chandigarh', 'Dadra and Nagar Haveli and Daman and Diu', 'Delhi', 'Jammu and Kashmir', 'Ladakh', 'Lakshadweep', 'Puducherry',
    ];
}

/** Canonical Indian state / UT name for loose input ("up", "UTTAR PRADESH", "Orissa", "NCT of Delhi"); other countries: trimmed text. */
function address_state_normalize(?string $state, string $country = 'IN'): ?string
{
    $s = trim((string) preg_replace('/\s+/', ' ', (string) $state));
    if ($s === '') {
        return null;
    }
    if (strtoupper($country) !== 'IN') {
        return mb_substr($s, 0, 80);
    }
    $key = strtolower((string) preg_replace('/[^a-z]/i', '', str_replace('&', 'and', $s)));
    $aliases = ['up' => 'Uttar Pradesh', 'mp' => 'Madhya Pradesh', 'ap' => 'Andhra Pradesh', 'hp' => 'Himachal Pradesh', 'uk' => 'Uttarakhand', 'uttaranchal' => 'Uttarakhand',
        'wb' => 'West Bengal', 'tn' => 'Tamil Nadu', 'jk' => 'Jammu and Kashmir', 'orissa' => 'Odisha', 'pondicherry' => 'Puducherry', 'nctofdelhi' => 'Delhi', 'newdelhi' => 'Delhi',
        'ncr' => 'Delhi', 'andamanandnicobar' => 'Andaman and Nicobar Islands', 'damananddiu' => 'Dadra and Nagar Haveli and Daman and Diu',
        'dadraandnagarhaveli' => 'Dadra and Nagar Haveli and Daman and Diu', 'jammuandkashmir' => 'Jammu and Kashmir', 'chattisgarh' => 'Chhattisgarh'];
    if (isset($aliases[$key])) {
        return $aliases[$key];
    }
    foreach (address_india_states() as $name) {
        if (strtolower((string) preg_replace('/[^a-z]/i', '', $name)) === $key) {
            return $name;
        }
    }
    return null;
}

/** " & " -> " and ", curly apostrophes -> ', bracketed parts removed: "Myanmar (Burma)" -> "Myanmar". */
function address_plain_name(string $name): string
{
    $name = str_replace([' & ', '’', '‘'], [' and ', "'", "'"], $name);
    return trim((string) preg_replace('/\s*\([^)]*\)/', '', $name));
}

/** Sort key ignoring case and accents ("Åland Islands" sorts with A, "Curaçao" with C). */
function address_sort_key(string $name): string
{
    static $map = null;
    $map ??= array_combine(
        preg_split('//u', 'ÀÁÂÃÄÅàáâãäåÇçÈÉÊËèéêëÌÍÎÏìíîïÑñÒÓÔÕÖØòóôõöøÙÚÛÜùúûüÝýÿŚśŻżŁłŞşĞğİı', -1, PREG_SPLIT_NO_EMPTY),
        str_split('AAAAAAaaaaaaCcEEEEeeeeIIIIiiiiNnOOOOOOooooooUUUUuuuuYyySsZzLlSsGgIi')
    );
    return strtolower(strtr($name, $map));
}

/** Comparison key: accent-free lowercase words ("Côte d'Ivoire" -> "cote d ivoire"). */
function address_match_key(string $name): string
{
    return trim((string) preg_replace('/[^a-z0-9]+/', ' ', address_sort_key($name)));
}

/**
 * Country lookup by ISO2 code, English name or common alias ("USA", "UK", "UAE", "Bharat").
 * @return array{iso:string, name:string, dial:string}|null
 */
function address_country(?string $value): ?array
{
    $v = trim((string) $value);
    if ($v === '') {
        return null;
    }
    $regions = phone_meta()['regions'];
    $upper = strtoupper($v);
    if (strlen($v) === 2 && isset($regions[$upper])) {
        return ['iso' => $upper, 'name' => phone_country_name($upper), 'dial' => (string) $regions[$upper]['c']];
    }
    $key = address_match_key(address_plain_name($v));
    $aliases = ['usa' => 'US', 'u s a' => 'US', 'united states of america' => 'US', 'america' => 'US', 'uk' => 'GB', 'u k' => 'GB', 'great britain' => 'GB', 'britain' => 'GB',
        'england' => 'GB', 'scotland' => 'GB', 'wales' => 'GB', 'uae' => 'AE', 'u a e' => 'AE', 'emirates' => 'AE', 'dubai' => 'AE', 'bharat' => 'IN', 'hindustan' => 'IN',
        'ksa' => 'SA', 'saudi' => 'SA', 'turkey' => 'TR', 'czech republic' => 'CZ', 'burma' => 'MM', 'ivory coast' => 'CI', 'south korea' => 'KR', 'korea' => 'KR',
        'north korea' => 'KP', 'russia' => 'RU', 'russian federation' => 'RU', 'vietnam' => 'VN', 'viet nam' => 'VN', 'holland' => 'NL', 'hong kong' => 'HK', 'macau' => 'MO',
        'eswatini' => 'SZ', 'swaziland' => 'SZ', 'east timor' => 'TL', 'cape verde' => 'CV', 'congo' => 'CG', 'drc' => 'CD', 'palestine' => 'PS'];
    if (isset($aliases[$key])) {
        $iso = $aliases[$key];
        return ['iso' => $iso, 'name' => phone_country_name($iso), 'dial' => (string) $regions[$iso]['c']];
    }
    foreach ($regions as $iso => $r) {
        if ($key === address_match_key(address_plain_name((string) $r['n'])) || $key === address_match_key((string) $r['n'])) {
            return ['iso' => $iso, 'name' => phone_country_name($iso), 'dial' => (string) $r['c']];
        }
    }
    return null;
}

/**
 * Postal code formats (regex, case-insensitive) for countries that use them on letters. Countries not listed here
 * (UAE, Qatar, Hong Kong …) have no mandatory postal code: the field becomes optional and is only length-checked.
 */
function address_postal_patterns(): array
{
    return [
        'IN' => '^[1-9]\d{5}$', 'US' => '^\d{5}(?:-\d{4})?$', 'CA' => '^[ABCEGHJ-NPRSTVXY]\d[ABCEGHJ-NPRSTV-Z] ?\d[ABCEGHJ-NPRSTV-Z]\d$',
        'GB' => '^(?:GIR ?0AA|[A-PR-UWYZ](?:\d{1,2}|[A-HK-Y]\d(?:\d|[ABEHMNPRV-Y])?|\d[A-HJKPS-UW]) ?\d[ABD-HJLNP-UW-Z]{2})$',
        'AU' => '^\d{4}$', 'NZ' => '^\d{4}$', 'SG' => '^\d{6}$', 'MY' => '^\d{5}$', 'NP' => '^\d{5}$', 'BD' => '^\d{4}$', 'LK' => '^\d{5}$', 'BT' => '^\d{5}$',
        'PK' => '^\d{5}$', 'AF' => '^\d{4}$', 'MV' => '^\d{5}$', 'SA' => '^\d{5}(?:-\d{4})?$', 'KW' => '^\d{5}$', 'OM' => '^\d{3}$', 'BH' => '^\d{3,4}$',
        'JP' => '^\d{3}-?\d{4}$', 'CN' => '^\d{6}$', 'KR' => '^\d{5}$', 'TW' => '^\d{3}(?:\d{2,3})?$', 'TH' => '^\d{5}$', 'ID' => '^\d{5}$', 'PH' => '^\d{4}$',
        'VN' => '^\d{6}$', 'DE' => '^\d{5}$', 'FR' => '^\d{5}$', 'IT' => '^\d{5}$', 'ES' => '^\d{5}$', 'NL' => '^\d{4} ?[A-Z]{2}$', 'BE' => '^\d{4}$',
        'CH' => '^\d{4}$', 'AT' => '^\d{4}$', 'SE' => '^\d{3} ?\d{2}$', 'NO' => '^\d{4}$', 'DK' => '^\d{4}$', 'FI' => '^\d{5}$', 'PL' => '^\d{2}-\d{3}$',
        'PT' => '^\d{4}-\d{3}$', 'IE' => '^(?:[AC-FHKNPRTV-Y]\d{2}|D6W) ?[0-9AC-FHKNPRTV-Y]{4}$', 'RU' => '^\d{6}$', 'UA' => '^\d{5}$', 'TR' => '^\d{5}$',
        'ZA' => '^\d{4}$', 'NG' => '^\d{6}$', 'KE' => '^\d{5}$', 'EG' => '^\d{5}$', 'MU' => '^\d{5}$', 'BR' => '^\d{5}-?\d{3}$', 'MX' => '^\d{5}$',
    ];
}

/** "PIN code" (India), "ZIP code" (US), "Postcode" (UK, Australia …), else "Postal code". */
function address_postal_label(string $country): string
{
    return ['IN' => 'PIN code', 'US' => 'ZIP code', 'GB' => 'Postcode', 'AU' => 'Postcode', 'NZ' => 'Postcode', 'IE' => 'Eircode'][strtoupper($country)] ?? 'Postal code';
}

/** Whether a postal code is expected for the country (it has a pattern in address_postal_patterns()). */
function address_postal_required(string $country): bool
{
    return isset(address_postal_patterns()[strtoupper($country)]);
}

/** Uppercase + single spaces ("sw1a 1aa" -> "SW1A 1AA"); digits-only countries lose stray spaces ("201 310" -> "201310"). */
function address_postal_normalize(?string $code, string $country = 'IN'): ?string
{
    $c = strtoupper(trim((string) preg_replace('/\s+/', ' ', (string) $code)));
    if ($c === '') {
        return null;
    }
    if (in_array(strtoupper($country), ['IN', 'SG', 'CN', 'RU', 'VN', 'NG', 'AU', 'NZ', 'DE', 'FR', 'IT', 'ES', 'MX', 'NP', 'LK', 'BT', 'PK'], true)) {
        $c = str_replace(' ', '', $c);
    }
    return $c;
}

/** Validation message for a postal code (null when valid); $label defaults to the country's postal label. */
function address_postal_error(?string $code, string $country = 'IN', ?string $label = null): ?string
{
    $country = strtoupper($country);
    $c = address_postal_normalize($code, $country);
    if ($c === null) {
        return null;
    }
    $label ??= address_postal_label($country);
    $pattern = address_postal_patterns()[$country] ?? null;
    if ($pattern === null) {
        return preg_match('/^[A-Z0-9][A-Z0-9 \-]{1,10}$/', $c) ? null : 'Enter a valid ' . address_label_lower($label) . '.';
    }
    if (preg_match('/' . $pattern . '/i', $c)) {
        return null;
    }
    return $country === 'IN' ? 'Enter a valid 6-digit PIN code.' : 'Enter a valid ' . address_label_lower($label) . ' for ' . phone_country_name($country) . '.';
}

/** Label inside a sentence: "Postal code" -> "postal code", acronyms kept ("ZIP code", "PIN code"). */
function address_label_lower(string $label): string
{
    return preg_match('/^[A-Z]{2}/', $label) ? $label : lcfirst($label);
}
